-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (628, '1', $t$ASK 628: the Oracle's close answers every verse pressed against it (re-call once, then show the judges what is still open)$t$,
  $t$In run 42373 the Oracle defender's close left 20 of the 31 verses pressed against it with no ANSWER line, and the run went on. The engine already found them (the record-only CLOSE PRESS LIST audit line of ASK 556, Build Save Body). This ASK makes the engine act on that list before the judges grade: the close prompt lists the pressed verses; the one existing re-call of the close names any verse left with no ANSWER line; the judges are shown any verse still open after it. Oracle defender only. (plan rev 1, OBJECTIVE and CHANGES, ask628/w4/plan628.md md5 d3ee0e22, sha256 42c75705)$t$,
  'in part',
  $t$Written by W4 at 18:45 to 18:47 CST 2026-11-24 on the operator's press, and read back MATCH by W1 (Wall 11832, 11835; audit 41828). Engine 560f01fb to 634afc23, six nodes (Shared Library, Build Save Body, D4 Build, D4B Build, Panel Build, Build Independent Verdict); child b1d5a5bf to 85515391, Shared Library only. IN PART because it is shown offline only: on the stored rounds of run 42373 (t628.cjs, 30 checks, ALL PASS) the audit line is byte-equal to the stored one (31 pressed, 20 open); the Oracle close prompt carries the 31 verses; the whole D4B node re-calls that close naming the 20, where the engine before did not re-call it; the judges' request carries the 20; with every verse answered, or with a defender that is not the Oracle, nothing changes; a press in the challenger's close changes none of the three lists. NOT SHOWN: no live run has gone through the change; a debater-input change is proven only by the debater's output, so whether the Oracle then writes an ANSWER line for each listed verse is unknown. Narrowing stated on the choice card: the operator's approval named no profile and the build acts for the Oracle defender only (W1 N1, Wall 11823). The list counts [L1] and [L3] lines alike, so supporting verses are listed too (W1 N3). Open: two clean live runs with an Oracle defender (the operator's rule of 10:38 CST 2026-11-24); the engine manual entry (draft 2 graded PASS, Wall 11839, not written).$t$,
  '11777, 11812, 11819, 11823, 11826, 11830, 11831, 11832, 11835, 11836, 11839',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$(1) Project chat, 18:03 CST 2026-11-24: "which of these do the team thinks we should or need to act on?" with the four WALL-11777 items; 18:07 CST: "4a.  approved" (with "2c. hold for now", "4b. hold for now", "1d. denied."); recorded by W3 at Wall 11812 and in md_notes_rulings of seat 33. (2) W4's choice card "When the Oracle's close leaves pressed verses unanswered, what should happen?": he pressed "Both" at 18:18 CST. (3) W4's write card "Write ASK 628 (Oracle close answers every pressed verse) to live now?": he pressed "Write it" at 18:45 CST. The card ids, questions, options and press times of (2) and (3) are W4's, from its thread note to W3 of 18:52 CST; W3 did not read those cards.$t$::text),
  $j${"answer": "Write it", "question": "Write ASK 628 (Oracle close answers every pressed verse) to live now?", "thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo586FsLjacrjATJAz4gnW5NV7", "press_time": "18:45 CST 2026-11-24", "options": "Write it / Hold", "source": "W4's thread note to W3, 18:52 CST 2026-11-24; audit 41828 (names the card id); Wall 11832. Not read by W3.", "choice_card": {"thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo58Kp5f8H2wJ1S6vnCJkhKbuE", "question": "When the Oracle's close leaves pressed verses unanswered, what should happen?", "options": "Re-call the close once / Show the judges the list / Both", "answer": "Both", "press_time": "18:18 CST 2026-11-24", "source": "W4's thread note to W3, 18:52 CST; Wall 11826. Not read by W3."}, "approval": {"where": "project chat", "words": "4a.  approved", "time": "18:07 CST 2026-11-24", "source": "Wall 11812 (W3); md_notes_rulings of seat 33"}}$j$::jsonb,
  'W4',
  $j${"md5": "d3ee0e22", "sha256_prefix": "42c75705", "path": "ask628/w4/plan628.md", "note": "plan rev 1; rev 0 (md5 d68b3efe, sha256 beb213b8) graded PASS WITH N1, N2, N3 by W1 (Wall 11823); rev 1 applies N1 to N3 and nothing else by W1's diff (Wall 11831). No Wall post of rev 1 by itself was found by W3.", "source": "Wall 11819, 11823, 11831; md5sum and sha256sum by W3"}$j$::jsonb,
  $j$[{"md5": "be69757c", "sha256_prefix": "79a7c0ec", "path": "ask628/w4/b1/target_engine_628.json", "note": "the engine target as written; notes628.md names it by the sha256 prefix", "source": "md5sum and sha256sum by W3; Wall 11831, 11835"}, {"md5": "666f18e3", "sha256_prefix": "90275694", "path": "ask628/w4/b1/target_child_628.json", "note": "the child target as written; Shared Library only", "source": "md5sum and sha256sum by W3; Wall 11831, 11835"}, {"md5": "e50f4d73", "path": "ask628/w4/b1/notes628.md", "note": "build notes; Wall 11830 names it d3bb7916, a sha256 prefix by the notes' own first line (not recomputed by W3)", "commit": "f91c0ae0", "source": "md5sum by W3; Wall 11830"}, {"md5": "d18dc590", "path": "ask628/w4/b1/b628.cjs", "note": "builds the targets (then ask579 fixhdr579.js resets the Library header)", "source": "md5sum by W3; notes628.md"}, {"md5": "acbb3743", "path": "ask628/w4/b1/presslib628.js", "note": "the PRESS LIST Library entry, 7 lines", "source": "md5sum by W3; notes628.md"}, {"md5": "5ea712b6", "path": "ask628/w4/b1/t628.cjs", "note": "the test, 30 checks", "source": "md5sum by W3"}, {"md5": "04fd3e10", "path": "ask628/w4/b1/out_t628.txt", "note": "test output, ALL PASS", "source": "md5sum and read by W3"}, {"md5": "d3cdddf4", "path": "ask628/w4/write/write628.sh", "note": "the write script (notes name it 1327c00e, a sha256 prefix)", "source": "md5sum by W3; Wall 11830, 11831"}, {"md5": "4a3b4da9", "path": "ask628/w4/write/write628_run.txt", "note": "the write's own output: both PUTs http 200; engine 634afc23-e56a-4bcd-ad1c-4e75753fa1dc active, 423 nodes, params equal put, connections equal, changed the six nodes; child 85515391-82cc-49e0-b067-cee611dd60cf active, 156 nodes, changed Shared Library only; standing 31 PASS, 0 FAIL before and after; pair Library Check PASSES (lib 027c8c4a71282403, map 771e35cfe3e3b51b); ALL PASS", "source": "md5sum and read by W3"}, {"md5": "cdfe8fae", "path": "ask628/w4/write/fetchback_eng_628.json", "note": "engine fetch-back after the write", "source": "md5sum by W3"}, {"md5": "9cd4833c", "path": "ask628/w4/write/fetchback_child_628.json", "note": "child fetch-back after the write", "source": "md5sum by W3"}]$j$::jsonb,
  $j${"engine": {"path": "ask628/w4/write/revert_eng_628.json", "md5": "7047ce00", "note": "the engine before ASK 628 (560f01fb), made at the write"}, "child": {"path": "ask628/w4/write/revert_child_628.json", "md5": "a78d78e9", "note": "the child before ASK 628 (b1d5a5bf), made at the write"}, "database": "none: no database object was changed", "rehearsed": "no", "source": "md5sum by W3; audit 41828; Wall 11832"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS WITH N1, N2, N3 (plan rev 0)", "wall_id": 11823, "md5_graded": "d68b3efe", "verdict_norm": "PASS", "source": "Wall 11823; fairjudge/w1/g628/grade_plan628_r0.md (commit 8e05fd5f)"}, {"seat": "W1", "verdict": "PASS (build b1, engine target: W1's rebuild is byte-equal to the targets; W1 names no target hash in the post; the md5 here is W3's md5sum of the target file W1 graded)", "wall_id": 11831, "md5_graded": "be69757c", "verdict_norm": "PASS", "source": "Wall 11831; fairjudge/w1/g628/grade_build628_b1.md (commit af10a263)"}, {"seat": "W1", "verdict": "PASS (build b1, child target; the same grade)", "wall_id": 11831, "md5_graded": "666f18e3", "verdict_norm": "PASS", "source": "Wall 11831; fairjudge/w1/g628/grade_build628_b1.md (commit af10a263)"}]$j$::jsonb,
  ARRAY['be69757c', '666f18e3'], '[41828]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 (engine)", "before": "560f01fb", "after": "634afc23-e56a-4bcd-ad1c-4e75753fa1dc (18:45 to 18:47 CST), active, 423 nodes; six nodes changed: Shared Library, Build Save Body, D4 Build, D4B Build, Panel Build, Build Independent Verdict; Library sha 027c8c4a71282403, 3858 lines, map 771e35cfe3e3b51b"}, {"kind": "n8n workflow", "name": "child", "before": "b1d5a5bf", "after": "85515391-82cc-49e0-b067-cee611dd60cf, active, 156 nodes, Shared Library only"}, {"kind": "Shared Library entry (engine and child)", "name": "PRESS LIST", "before": "the reader stood inline in Build Save Body", "after": "one Library entry; Build Save Body, D4 Build, D4B Build, Panel Build and Build Independent Verdict read through it"}, {"kind": "prompt text (Oracle defender only)", "name": "D4 close prompt; D4B re-call note; the judges' line after the PRESSED-WITNESS LEDGER", "before": "none", "after": "the three texts of notes628.md CHANGES 3, 4 and 5; no instruction to the judges added or changed"}]$j$::jsonb,
  $j$[{"name": "t628.cjs on the stored rounds of run 42373 (fx/r42373.json), 30 checks", "result": "ALL PASS by W4, by W1 from scratch copies (identical), and on the live fetch-back by W4 and W1. C1 audit line byte-equal old, new and stored (31 pressed, 20 open); C2 Oracle prompt carries the 31, other profiles unchanged; C2b a press in the challenger's close changes none of the three lists; C3 the whole D4B node re-calls the 42373 close naming the 20 in one request, where live did not re-call it; all answered adds nothing; C4 the judges get the 20, nothing when all answered or not Oracle; C5 only the six engine nodes and the child Library change, 73 MAP entries rebuild the same, all compile, every change tagged ASK 628.", "source": "out_t628.txt 04fd3e10; Wall 11830, 11831, 11832, 11835"}, {"name": "Standing set and pair Library Check", "result": "31 PASS, 0 FAIL; pair PASSES (lib 027c8c4a71282403, map 771e35cfe3e3b51b), at the build, at the write and on live", "source": "write628_run.txt 4a3b4da9; Wall 11831, 11835"}, {"name": "WRONG-IF margin (the close's output limit)", "result": "W4: the Opus defender row allows 64,000 output tokens; the 42373 close was 28,325 characters with 22 ANSWER lines, so 31 answers stay inside it. Not measured on a live call.", "source": "notes628.md"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "MATCH (engine 634afc23, 423 nodes, and child 85515391, 156 nodes, equal the graded targets on every node's parameters, other fields and connections; against 560f01fb and b1d5a5bf only the six engine nodes and the child Library changed; on live t628 ALL PASS, standing 31/0, pair PASSES)", "wall_id": 11835, "source": "Wall 11835; fairjudge/w1/g628/readback_628.md (commit 1c880a52)"}]$j$::jsonb,
  $j${"case": "NO RUN YET. Shown offline on the stored rounds of run 42373 only.", "runs": [], "mark_for_the_next_run": "with an Oracle defender: the D4 request carries \"THE VERSES PRESSED AGAINST YOU\" and the list; when the first close leaves a listed verse with no ANSWER line, one D4B re-call names it (its why reads \"<n> pressed verse(s) with no ANSWER line\"); the judges' request carries the PRESSED VERSES line only when a verse is still open after the close; the CLOSE PRESS LIST audit line stands once in review_notes. Two clean live runs are owed.", "not_shown": "that the Oracle writes an ANSWER line for each listed verse when asked; the cost of the extra close call when the re-call fires (W4's estimate: about $0.40 at list rates, one Opus close call).", "source": "notes628.md; plan628.md RUN EVIDENCE; Wall 11830"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "NOT WRITTEN. Draft 2 (manual1123/w3/a628/em_pairs_628_draft2.json, md5 00645152; part 11.1 v276 to 08a2d0a9, 42,461) graded PASS by W1 (Wall 11839); it needs its own card and no run live. A revision row records the write and the run evidence."}$j$::jsonb,
  'read back', $j$[11777, 11812, 11819, 11823, 11826, 11830, 11831, 11832, 11835, 11836, 11839]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
